import { test, expect } from '@playwright/test';

test.describe('Modal Scroll Prevention', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should prevent page scroll when modal is open', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Get the initial scroll position of the page content
    const pageContent = page.locator('[data-testid="page-content"]');
    const initialScrollY = await pageContent.evaluate((el) => el.scrollTop);

    // Scroll the page content to test scroll prevention
    await pageContent.evaluate((el) => {
      el.scrollTop = 1000;
    });

    // Verify scroll position did not change
    const finalScrollY = await pageContent.evaluate((el) => el.scrollTop);
    expect(finalScrollY).toBe(initialScrollY);

    // Verify modal is still visible
    await expect(modal).toBeVisible();
  });

  test('should allow page scroll when modal is closed', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Get the initial scroll position of the page content
    const pageContent = page.locator('[data-testid="page-content"]');
    const initialScrollY = await pageContent.evaluate((el) => el.scrollTop);

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Scroll the page content to verify scroll is now enabled
    await pageContent.evaluate((el) => {
      el.scrollTop = 1000;
    });

    // Verify scroll position has changed
    const finalScrollY = await pageContent.evaluate((el) => el.scrollTop);
    expect(finalScrollY).toBeGreaterThan(initialScrollY);
  });
});
